sp_header_footer.client_script:
api.controller = function($scope, $window, $http, spUtil, $location) {
    var c = this;

	$scope.instanceName = c.data.instanceName;

$scope.goToPage = function(id) {
    $scope.menuAberto = false;
    $scope.submenuFinancasAberto = false;
    $scope.submenuSistemasAberto = false;
    window.open("?id=" + id, '_blank');
};

$scope.goTo = function(url) {
    $scope.menuAberto = false;
    $scope.submenuFinancasAberto = false;
    $scope.submenuSistemasAberto = false;
    window.open(url, '_blank');
};

	  $scope.goToPageWithoutBlank = function(id) {
    $location.url("?id=" + id);
  };


	    function updateFlags() {
        var currentUrl = $location.absUrl();
        $scope.isHomePage = (currentUrl === "https://" + $scope.instanceName + ".service-now.com/sate");

        $scope.showHeaderMenu = (currentUrl === "https://" + $scope.instanceName + ".service-now.com/sate");
    }

    // Atualiza na inicialização
    updateFlags();

    // Observa mudanças na URL para atualizar
    $scope.$watch(function() {
        return $location.absUrl();
    }, function(newVal, oldVal) {
        if (newVal !== oldVal) {
				$scope.menuAberto = false;
        $scope.submenuFinancasAberto = false;
        $scope.submenuSistemasAberto = false;
        $scope.dropdownOpen = false;
            updateFlags();
        }
    });



    var highContrastEnabled = false;

	     var currentUrl = window.location.href;
  		$scope.showHeaderMenu = currentUrl === "https://" + $scope.instanceName + ".service-now.com/sate";

$scope.isHomePage = (currentUrl === "https://" + $scope.instanceName + ".service-now.com/sate");


  $scope.menuAberto = false;
  $scope.submenuFinancasAberto = false;

  $scope.toggleMenu = function() {
    $scope.menuAberto = !$scope.menuAberto;
  };

  $scope.toggleSubmenuFinancas = function($event) {
    $event.stopPropagation(); // evita fechar o menu pai
    $scope.submenuFinancasAberto = !$scope.submenuFinancasAberto;
  };

	$scope.submenuSistemasAberto = false;

$scope.toggleSubmenuSistemas = function($event) {
  $event.stopPropagation();
  $scope.submenuSistemasAberto = !$scope.submenuSistemasAberto;
};

    // Funcionalidade de login
    c.checkUserLoggedIn = function() {
        if ($scope.user && $scope.user.logged_in) {
            c.loginButtonText = $scope.user.name;
            $scope.dropdownOpen = false;

            $scope.toggleDropdown = function() {
                $scope.dropdownOpen = !$scope.dropdownOpen;
            };

            // Função de logout ajustada para desconexão e permanência na mesma página
            $scope.logout = function() {
                // Executa o logout via GET (isso pode ser modificado dependendo da sua configuração)
                var logoutRequest = new XMLHttpRequest();
                logoutRequest.open("GET", "/logout", true);
                logoutRequest.onload = function() {
                    // Após a requisição de logout, redireciona para a página /gfo
                    $window.location.href = '/gfo';
                };
                logoutRequest.send();
            };

            $scope.avatarProfile = {
                initials: $scope.user.first_name[0] + $scope.user.last_name[0]
            };
        } else {
            c.loginButtonText = 'Entrar';
            c.redirect = function() {
                $window.location.href = '/login_with_sso.do?glide_sso_id=13e4f3d2fb2bca10f6d5f9d38eefdcce';
            };
        }
    };

	 // Função para redirecionar para "Meus Pedidos" com verificação de login
    c.goToPedidos = function() {
        if ($scope.user && $scope.user.logged_in) {
            // Se estiver logado, redireciona para "Meus Pedidos"
            $window.location.href = '?id=gfo_minhas_solicitacoes';
        } else {
            // Se não estiver logado, redireciona para o login SSO
            $window.location.href = '/login_with_sso.do?glide_sso_id=13e4f3d2fb2bca10f6d5f9d38eefdcce';
        }
    };

    // Ajuste de fonte
    $scope.adjustFontSize = function(factor) {
        var elements = document.querySelectorAll('body, body *');
        elements.forEach(function(element) {
            if (element.tagName !== 'IMG' && element.children.length === 0) {
                var currentSize = window.getComputedStyle(element).fontSize;
                var newSize = parseFloat(currentSize) * factor;
                element.style.fontSize = newSize + 'px';
            }
        });
    };

		$scope.letter = 'a';  // estado interno

$scope.toggleCase = function() {
  if ($scope.letter === 'a') {
    $scope.letter = 'A';
  } else {
    $scope.letter = 'a';
  }

  console.log('Letra agora está:', $scope.letter);
};

$scope.isLowercase = null; // começa normal

$scope.toggleCase = function() {
  if ($scope.isLowercase === null) {
    $scope.isLowercase = true;   // minúsculo
  } else if ($scope.isLowercase === true) {
    $scope.isLowercase = false;  // maiúsculo
  } else {
    $scope.isLowercase = null;   // normal
  }

  // Emite o evento para sincronizar nos outros widgets
  $scope.$root.$broadcast('toggleCaseEvent', $scope.isLowercase);

  console.log('Estado agora:', $scope.isLowercase);
};





    // Função para alternar contraste
    $scope.toggleContrast = function(event) {
        event.preventDefault(); // Evitar qualquer comportamento padrão do link
        highContrastEnabled = !highContrastEnabled;
       // var elements = document.querySelectorAll('body, body *');

			var allElements = document.querySelectorAll('body, body *');

allElements.forEach(function(element) {
    // Ignora elementos que estão dentro de .destaques-main-container
    if (element.closest('.destaques-main-container')) {
        return;
    }

    if (highContrastEnabled) {
        element.style.backgroundColor = "#000000";
        element.style.color = "#FFFFFF";
    } else {
        element.style.backgroundColor = "";
        element.style.color = "";
    }
	var fiscalCards = document.getElementsByClassName('fiscal-card');
				for (var m = 0; m < fiscalCards.length; m++) {
						fiscalCards[m].style.border = highContrastEnabled ? "2px solid #FFFFFF" : ""; // Borda branca ou reset
						fiscalCards[m].style.borderRadius = highContrastEnabled ? "8px" : ""; // (opcional) Arredondamento
				}

				var fiscalLabels = document.getElementsByClassName('fiscal-label');
				for (var n = 0; n < fiscalLabels.length; n++) {
						fiscalLabels[n].style.backgroundColor = highContrastEnabled ? "#FFFFFF" : ""; // fundo branco ou reset
						fiscalLabels[n].style.color = highContrastEnabled ? "#000000" : ""; // texto preto no fundo branco
						fiscalLabels[n].style.padding = highContrastEnabled ? "4px 8px" : ""; // (opcional) espaçamento interno
						fiscalLabels[n].style.borderRadius = highContrastEnabled ? "4px" : ""; // (opcional) cantos arredondados
				}

	var acessosWidgets = document.getElementsByClassName('acessos-widget');
for (var k = 0; k < acessosWidgets.length; k++) {
    acessosWidgets[k].style.border = highContrastEnabled ? "2px solid #FFFFFF" : "";
    acessosWidgets[k].style.borderRadius = highContrastEnabled ? "10px" : "";
    acessosWidgets[k].style.padding = highContrastEnabled ? "15px" : "";
}


